namespace docking.menu;







using org.apache.commons.lang3;
using org.apache.commons.lang3;

using docking.action;
using ghidra.docking.util;
using ghidra.util;

public class DockingToolBarUtils {

	private static readonly string START_KEYBINDING_TEXT = "<BR><HR><CENTER>(";
	private static readonly string END_KEYBINDNIG_TEXT = ")</CENTER>";

	/**
	 * Sets the given button's tooltip text to match that of the given action
	 * @param button the button
	 * @param action the action
	 */
	public static void setToolTipText(JButton button, DockingActionIf action) {
		string text = createToolTipText(button, action);
		button.setToolTipText(text);
	}

	/**
	 * Creates tooltip text for the given action and button.  This is intended to be used for 
	 * buttons that represent the given action.
	 * @param button the button that is the target for the text
	 * @param action the action that is the source of the button
	 * @return the text
	 */
	public static string createToolTipText(JButton button, DockingActionIf action) {
		string toolTipText = getToolTipText(action);
		string keyBindingText = getKeyBindingAcceleratorText(button, action.getKeyBinding());
		if (keyBindingText != null) {
			return combineToolTipTextWithKeyBinding(toolTipText, keyBindingText);
		}
		return toolTipText;
	}

	private static string combineToolTipTextWithKeyBinding(string toolTipText,
			string keyBindingText) {
		StringBuilder buffy = new StringBuilder(toolTipText);
		if (StringUtilities.startsWithIgnoreCase(toolTipText, "<html>")) {
			string endHTMLTag = "</html>";
			int closeTagIndex = Strings.CI.indexOf(toolTipText, endHTMLTag);
			if (closeTagIndex < 0) {
				// no closing tag, which is acceptable
				buffy.append(START_KEYBINDING_TEXT)
						.append(keyBindingText)
						.append(END_KEYBINDNIG_TEXT);
			}
			else {
				// remove the closing tag, put on our text, and then put the tag back on
				buffy.delete(closeTagIndex, closeTagIndex + endHTMLTag.length() + 1);
				buffy.append(START_KEYBINDING_TEXT)
						.append(keyBindingText)
						.append(END_KEYBINDNIG_TEXT)
						.append(endHTMLTag);
			}
			return buffy.toString();
		}

		// plain text (not HTML)
		return toolTipText + " (" + keyBindingText + ")";
	}

	private static string getToolTipText(DockingActionIf action) {
		string description = action.getDescription();
		if (!StringUtils.isEmpty(description)) {
			return description;
		}
		return action.getName();
	}

	private static string getKeyBindingAcceleratorText(JButton button, KeyStroke keyStroke) {
		if (keyStroke == null) {
			return null;
		}

		// This code is based on that of BasicMenuItemUI
		StringBuilder builder = new StringBuilder();
		int modifiers = keyStroke.getModifiers();
		if (modifiers > 0) {
			builder.append(InputEvent.getModifiersExText(modifiers));

			// The Aqua LaF does not use the '+' symbol between modifiers
			if (!LookAndFeelUtils.isUsingAquaUI(button.getUI())) {
				builder.append('+');
			}
		}
		int keyCode = keyStroke.getKeyCode();
		if (keyCode != 0) {
			builder.append(KeyEvent.getKeyText(keyCode));
		}
		else {
			builder.append(keyStroke.getKeyChar());
		}
		return builder.toString();
	}
}
